scripts.龚楷对话.txt:
// 和龚揩对话

	If ($Event == 540) @Event540;
	If ($Event == 550) @Event550;
	
	Say("龚揩：怎么还不快进暗门，会被人发现的！", 92);
	Return;

@Event540:
	If ($Talkgongkai == 0) @Talkgongkai0;
	If ($Talkgongkai == 1) @Talkgongkai1;
	If ($Talkgongkai == 2) @Talkgongkai2;
	If ($Talkgongkai == 3) @Talkgongkai3;
 @Talkgongkai0:
	Say("茶馆掌柜：在下龚楷，是这里的掌柜。客官要喝什么茶？", 92);
	Assign($Talkgongkai,1);
	Return;
 @Talkgongkai1:
	Say("龚楷：饮茶可是大有讲究。若是口干舌燥，将茶水一饮而尽方觉畅快，那叫驴饮，就是“喝茶”二字也配不起的。", 92);	
	Assign($Talkgongkai,2);
	Return;
 @Talkgongkai2:	
	Say("龚楷：若论品茶，其中就大有学问了。且不说茶，单说烹茶的水，就有很多的讲究。", 92);
	Say("龚楷：烹茶之水，泉水最好，江水次之，井水最差。烹茶之水要用活火煮之，所谓活火就是有火焰的炭火，煮水时又有文火武火之分。水开始冒出像鱼眼似的水泡并发出很小的声响叫一沸，水泡像连珠似的涌出叫二沸，水花飞溅时叫三沸。三沸时的水刚好纯熟，再煮就是老水了。", 92);
	Say("龚楷：烹茶时，茶叶要先用热水洗去表面的尘土和冷气，先放茶叶后注开水叫下投；开水注了一半后放茶叶，再将开水注满，叫做中投；先注开水后放茶叶叫做上投。春秋时节要中投，夏天要上投，冬天要下投。", 92);
	Say("张琳心：喝茶还有这么多讲究？只怕我们是没有功夫来喝你的茶了。", 21);
	Say("龚楷：哈哈，我若是每壶茶都这么来烹，恐怕早就饿死了。我这村野小店，自然不会有这么多的讲究，不过是为路人解渴罢了", 92);
	Assign($Talkgongkai,3);
	Return;
 @Talkgongkai3:
	Say("龚楷：在下讲了这么多，客官怎么也得来杯茶吧？", 92);
	Return;
	
@Event550:
	Say("龚楷：这位客官要点什么……", 92);
	Say("独孤剑：在下只是出来看看朋友！", 1);
	Say("龚楷：哦！朋友远行江湖，可曾带了防身的当头？", 92);
	Say("独孤剑：不知这个可否足以防身……", 2);
	Sleep(200);
	Say("独孤剑拿出“天王令”。");
	Sleep(200);
	Say("龚楷：天王令！……几位请随我来。", 92);

	NpcGoto("龚楷", 4, 16);
	NpcGoto("龚楷", 3, 14);
	NpcGoto("龚楷", 6, 9);
	SetNpcDir("龚楷", 1);
	
	SetNpcKind("张如梦", 1);
	SetNpcKind("张琳心", 1);
	PlayerGotoEx(6, 10);
	NpcGotoEx("张如梦", 5, 11);
	Sleep(200);
	NpcGoto("张琳心", 3, 14);
	Sleep(200);
	NpcGoto("张琳心", 4, 12);
	NpcGoto("张琳心", 6, 12);
	Sleep(200);
	SetPlayerDir(5);
	SetNpcDir("张如梦", 5);
	SetNpcDir("张琳心", 4);
	
	Say("龚楷：见天王令如见帮主，公子有何吩咐，龚楷自当从命。", 92);
	Say("独孤剑：龚老板，我们有事要见帮主！", 1);
	Say("龚楷：这……好吧，但只能公子一人持令上天王岛面见帮主，这两位留在小店，小的自会安排打点，还请公子见谅。", 92);
	Say("张琳心：我们为什么不能进去？", 21);
	Say("龚楷：对不起，这是帮中的规矩，非本帮弟兄每次只能进去一人。", 92);
	SetPlayerDir(1);
	Say("独孤剑：张兄、琳儿，你们就留在这里，我会很快回来的。", 1);
	Say("张如梦：独孤兄要小心从事，我们就在此等候。", 11);
	Say("张琳心：独孤哥哥……千万要当心！", 24);
	Say("独孤剑：放心。", 2);
	SetPlayerDir(5);
	Say("龚楷：屏风后面是秘道的入口，公子从这里进去就能到达天王帮的总坛天王岛。", 92);
	NpcGoto("龚楷", 6, 8);
	SetNpcDir("龚楷", 7);
	SetMapTrap(2, "trap02.txt");
	Assign($Event, 560);
	Memo("独孤剑拿出天王令，茶馆老板遂将独孤剑带进密室，那儿有通向天王岛的秘道，但张如梦兄妹被挡在了外面。");
	PlayerGoto(7, 9);
	Return;

scripts.张如梦对话.txt:
// 和张如梦对话

	If ($Event == 540) @Event540;
	If ($Event == 550) @Event550;
	Return;
	
@Event540:	
	SetNpcDir("张如梦", 3);
	SetNpcKind("张琳心", 1);
	PlayerGoto(5, 25);
	SetPlayerDir(7);
	SetNpcPos("张琳心", 5, 26);
	SetNpcDir("张琳心", 6);
	SetNpcKind("张琳心", 3);
	
	Say("张琳心：哥哥，是你！", 95);
	Say("独孤剑：张兄？", 1);
	Say("张如梦：独孤兄，是你们！琳儿，你还好吗？", 12);
	Say("张琳心：琳儿很好。看到你没事，我就放心了。", 21);
	Say("张琳心：哥哥，家里……",24);
	Say("张如梦：秦桧狗贼已经将家里查抄了。我潜入秦府，将娘和爹的遗物拿了回来……", 11);
	Say("张琳心：那蒋伯他……",24);
	Say("张如梦：蒋伯……蒋伯他不肯离开，自尽在大堂里……",17);
	Say("张琳心：……",26);
	Say("独孤剑：……",9);
	Say("张如梦：我在临安调查“山河社稷图”的下落，终于有了消息。“山河社稷图”现在已经到了天王帮的手里。", 11);
	Say("独孤剑：我们也正是为此图而来。", 1);
	Say("张如梦：哦？那太好了！天王帮的总坛天王岛就在洞庭湖中，入口就在这附近。钟相、杨幺两次惨败都是因为官兵渗入腹地，所以现在天王帮防范极严，我在这里打探了数日也没有什么头绪。", 11);
	Say("张琳心：难道一点蛛丝马迹都没有吗？", 21);
	Say("张如梦：我发觉这茶馆的掌柜龚楷有些古怪，或许可以从他下手。", 11);
	Say("独孤剑：我这里有一块朋友所赠的天王令，不如在他身上试试。", 1);
	SetNpcKind("张如梦", 3);
	SetNpcRelation("张如梦", 2);
	Assign($Event, 550);
	Memo("独孤剑和张琳心在湖口村的茶馆里碰到张如梦，他打探到“山河社稷图”的遗失与天王帮有关，欲进天王岛一探，他怀疑茶馆老板好像与天王帮有些关系。");
	Return;
	
@Event550:
	Say("张如梦：我发觉这茶馆的掌柜龚楷有些古怪，或许可以从他下手。", 11);
	Return;

